-- BuildiFy WMS - 데모 시드 데이터 (Docker 초기화 전용)
-- 자동 생성 스크립트 결과물. 운영 데이터가 아닌 포트폴리오 데모용입니다.
--   로그인 계정: admin01 / admin1234!   ,  user01 / user1234!
--   날짜는 CURDATE() 기준 상대값이라 언제 컨테이너를 띄워도 대시보드가 채워집니다.
-- =====================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ---------- 관리자 (3) ----------

-- ---------- 사용자 (20) : user01~user20 / user1234!  (19,20번은 가입 미승인) ----------

-- ---------- 권한 (23) : role 0=사용자 / 1=관리자 ----------

-- ---------- 창고 지역 (5) ----------

-- ---------- 창고 위치 (5) ----------

-- ---------- 회원 창고 계약 (5) : 스키마상 창고당 1건(PK=ware_id) ----------

-- ---------- 카테고리 (12) ----------

-- ---------- 상품 (100) ----------

-- ---------- 재고 (100) ----------

-- ---------- 입고 요청 (120) : 상태 0 대기 / 1 승인 / 2 반려 ----------

-- ---------- 출고 요청 (100) : 상태 0 대기 / 1 승인 / 2 반려 ----------

SET FOREIGN_KEY_CHECKS = 1;

